/*
 Problem: 3876. Construct Uniform Parity Array II
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 166 MB (20.92%)
 Tags: Array, Math
*/
class Solution {
public:
    bool uniformArray(vector<int>& nums1) {
        int mn = *min_element(nums1.begin(), nums1.end());

        if (mn & 1) return true;

        for (const auto& x : nums1) {
            if (x & 1) return false;
        }
        return true;
    }
};
